import { useState } from "react";
import {
  ExternalLink,
  ChevronDown,
  CheckCircle2,
  XCircle,
  AlertCircle,
  Lock,
  FlaskConical,
  Loader2,
  Info,
  Copy,
  Check,
  AlertTriangle,
} from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

// ── Types ──────────────────────────────────────────────────────────────────────

type IntegrationStatus = "connected" | "server-side" | "missing";
type TestStatus = "idle" | "testing" | "success" | "failed";

interface EnvVar {
  name: string;
  description: string;
  resolved: boolean | null; // null = server-side secret (unknown to browser)
}

interface SetupStep {
  n: number;
  text: React.ReactNode;
}

interface IntegrationDef {
  id: string;
  name: string;
  subtitle: string;
  category: string;
  description: string;
  status: IntegrationStatus;
  iconComponent: React.FC<{ className?: string }>;
  accentColor: string; // Tailwind border-left accent when expanded
  envVars: EnvVar[];
  usedBy: string[];
  setupSteps: SetupStep[];
  externalUrl?: string;
  externalLabel?: string;
}

// ── Brand SVG Icons ────────────────────────────────────────────────────────────

function SupabaseIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 109 113"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="Supabase"
    >
      <defs>
        <linearGradient
          id="supabase_g1"
          x1="53.974"
          y1="54.974"
          x2="94.164"
          y2="71.83"
          gradientUnits="userSpaceOnUse"
        >
          <stop stopColor="#249361" />
          <stop offset="1" stopColor="#3ECF8E" />
        </linearGradient>
        <linearGradient
          id="supabase_g2"
          x1="36.156"
          y1="30.578"
          x2="54.484"
          y2="65.081"
          gradientUnits="userSpaceOnUse"
        >
          <stop />
          <stop offset="1" stopOpacity="0" />
        </linearGradient>
      </defs>
      <path
        d="M63.7076 110.284C60.8481 113.885 55.0502 111.912 54.9813 107.314L53.9738 40.0627H99.1935C107.384 40.0627 111.952 49.5228 106.951 55.9374L63.7076 110.284Z"
        fill="url(#supabase_g1)"
      />
      <path
        d="M63.7076 110.284C60.8481 113.885 55.0502 111.912 54.9813 107.314L53.9738 40.0627H99.1935C107.384 40.0627 111.952 49.5228 106.951 55.9374L63.7076 110.284Z"
        fill="url(#supabase_g2)"
        fillOpacity="0.2"
      />
      <path
        d="M45.317 2.071C48.1765 -1.53 53.9745 0.443 54.0434 5.041L54.485 72.292H9.831C1.64 72.292 -2.928 62.832 2.072 56.418L45.317 2.071Z"
        fill="#3ECF8E"
      />
    </svg>
  );
}

function GoogleIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="Google"
    >
      <path
        d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
        fill="#4285F4"
      />
      <path
        d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
        fill="#34A853"
      />
      <path
        d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
        fill="#FBBC05"
      />
      <path
        d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
        fill="#EA4335"
      />
    </svg>
  );
}

function AnthropicIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="Anthropic"
    >
      <path
        fill="#D97757"
        d="M13.827 3.52h-3.654L6 20h3.062l.78-2.361h4.273L14.9 20H18l-4.173-16.48zm-3.045 11.818 1.522-4.875 1.523 4.875H10.782z"
      />
    </svg>
  );
}

function ResendIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="Resend"
    >
      <path
        fill="currentColor"
        d="M3 5.5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v1.09a.5.5 0 0 1-.28.45L12 11.5 3.28 7.04A.5.5 0 0 1 3 6.59V5.5z"
      />
      <path
        fill="currentColor"
        d="M3 8.91v9.59a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V8.91l-8.72 4.46a.5.5 0 0 1-.56 0L3 8.91z"
      />
    </svg>
  );
}

function DodoPaymentsIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="Dodo Payments"
    >
      <rect x="2" y="5" width="20" height="14" rx="2" fill="currentColor" opacity="0.15" />
      <rect x="2" y="5" width="20" height="14" rx="2" stroke="currentColor" strokeWidth="1.5" fill="none" />
      <rect x="2" y="9" width="20" height="3" fill="currentColor" />
      <rect x="5" y="15" width="4" height="1.5" rx="0.75" fill="currentColor" />
      <rect x="10" y="15" width="3" height="1.5" rx="0.75" fill="currentColor" />
    </svg>
  );
}

function ScreenshotIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-label="Screenshot Service"
    >
      <path
        fill="currentColor"
        d="M9 2 7.17 4H4C2.9 4 2 4.9 2 6v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2h-3.17L13 2H9zm3 15a5 5 0 1 1 0-10 5 5 0 0 1 0 10z"
      />
      <circle cx="12" cy="12" r="3" fill="currentColor" />
    </svg>
  );
}

// ── Status computation ─────────────────────────────────────────────────────────

const dodoStatus: IntegrationStatus = import.meta.env.VITE_DODO_PUBLISHABLE_KEY
  ? "connected"
  : "server-side";

const supabaseStatus: IntegrationStatus =
  import.meta.env.VITE_SUPABASE_URL && import.meta.env.VITE_SUPABASE_ANON_KEY
    ? "connected"
    : "missing";

// ── Integration definitions ────────────────────────────────────────────────────

const INTEGRATIONS: IntegrationDef[] = [
  {
    id: "dodo",
    name: "Dodo Payments",
    subtitle: "Subscriptions · Checkout · Webhooks",
    category: "Billing",
    description:
      "Processes all subscription payments, manages plan upgrades and downgrades, and handles invoice generation for Free, Pro, and Agency tiers. Checkout sessions and customer portal sessions are created via Supabase edge functions.",
    status: dodoStatus,
    iconComponent: DodoPaymentsIcon,
    accentColor: "border-l-indigo-500",
    envVars: [
      {
        name: "DODO_SECRET_KEY",
        description: "Server-side secret key — used in dodo-checkout & dodo-portal edge functions",
        resolved: null,
      },
      {
        name: "DODO_WEBHOOK_SECRET",
        description: "Webhook signing secret — validates incoming Dodo Payments events",
        resolved: null,
      },
      {
        name: "DODO_PRICE_PRO_MONTHLY",
        description: "Product/Price ID for the Pro monthly plan",
        resolved: null,
      },
      {
        name: "DODO_PRICE_AGENCY_MONTHLY",
        description: "Product/Price ID for the Agency monthly plan",
        resolved: null,
      },
    ],
    usedBy: ["dodo-checkout", "dodo-portal", "dodo-webhook"],
    setupSteps: [
      {
        n: 1,
        text: (
          <>
            Go to{" "}
            <a
              href="https://dashboard.dodopayments.com"
              target="_blank"
              rel="noopener noreferrer"
              className="text-primary underline font-medium hover:opacity-80 transition-opacity"
            >
              dashboard.dodopayments.com
            </a>{" "}
            and copy your secret key from API Settings.
          </>
        ),
      },
      {
        n: 2,
        text: (
          <>
            In <strong>Supabase Dashboard → Project Settings → Edge Functions → Secrets</strong>, add{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              DODO_SECRET_KEY
            </code>{" "}
            and{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              DODO_WEBHOOK_SECRET
            </code>
            .
          </>
        ),
      },
      {
        n: 3,
        text: "Create a webhook endpoint in Dodo dashboard pointing to your dodo-webhook edge function URL.",
      },
      {
        n: 4,
        text: (
          <>
            Add product IDs for Pro and Agency plans as{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              DODO_PRICE_PRO_MONTHLY
            </code>{" "}
            and{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              DODO_PRICE_AGENCY_MONTHLY
            </code>
            .
          </>
        ),
      },
    ],
    externalUrl: "https://dashboard.dodopayments.com",
    externalLabel: "Dodo Dashboard",
  },
  {
    id: "anthropic",
    name: "Anthropic Claude API",
    subtitle: "claude-sonnet-4-20250514 · Vision + Text analysis",
    category: "AI Engine",
    description:
      "Powers all 7 CRO pillar analyses using Vision (screenshot) and Text, generating scored findings and AI rewrite suggestions for every scan. The model receives the page screenshot alongside the scraped HTML for combined multimodal analysis.",
    status: "server-side",
    iconComponent: AnthropicIcon,
    accentColor: "border-l-orange-400",
    envVars: [
      {
        name: "ANTHROPIC_API_KEY",
        description: "Claude API key — configured in Supabase Edge Function secrets, never exposed to the browser",
        resolved: null,
      },
    ],
    usedBy: ["analyze-url"],
    setupSteps: [
      {
        n: 1,
        text: (
          <>
            Go to{" "}
            <a
              href="https://console.anthropic.com/settings/keys"
              target="_blank"
              rel="noopener noreferrer"
              className="text-primary underline font-medium hover:opacity-80 transition-opacity"
            >
              console.anthropic.com
            </a>{" "}
            and create a new API key.
          </>
        ),
      },
      {
        n: 2,
        text: (
          <>
            Navigate to <strong>Supabase Dashboard → Project Settings → Edge Functions → Secrets</strong>.
          </>
        ),
      },
      {
        n: 3,
        text: (
          <>
            Add secret name{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              ANTHROPIC_API_KEY
            </code>{" "}
            and paste your key.
          </>
        ),
      },
      {
        n: 4,
        text: "Deploy the analyze-url edge function — it will automatically pick up the new secret on next cold start.",
      },
    ],
    externalUrl: "https://console.anthropic.com",
    externalLabel: "Anthropic Console",
  },
  {
    id: "pagespeed",
    name: "Google PageSpeed Insights",
    subtitle: "Core Web Vitals · Lighthouse scores",
    category: "Performance",
    description:
      "Provides Lighthouse-based performance scores, Core Web Vitals (LCP, FID, CLS), and diagnostic metrics for the Page Performance CRO pillar (9% weight). Runs on Google's infrastructure — no quota costs for moderate usage.",
    status: "server-side",
    iconComponent: GoogleIcon,
    accentColor: "border-l-blue-500",
    envVars: [
      {
        name: "PAGESPEED_API_KEY",
        description: "Google Cloud API key with PageSpeed Insights API enabled",
        resolved: null,
      },
    ],
    usedBy: ["pagespeed"],
    setupSteps: [
      {
        n: 1,
        text: (
          <>
            Go to{" "}
            <a
              href="https://console.cloud.google.com/apis/credentials"
              target="_blank"
              rel="noopener noreferrer"
              className="text-primary underline font-medium hover:opacity-80 transition-opacity"
            >
              Google Cloud Console → APIs & Services → Credentials
            </a>
            .
          </>
        ),
      },
      {
        n: 2,
        text: (
          <>
            Create an API key and enable the <strong>PageSpeed Insights API</strong> for that key.
          </>
        ),
      },
      {
        n: 3,
        text: (
          <>
            In Supabase Dashboard → <strong>Edge Functions → Secrets</strong>, add{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              PAGESPEED_API_KEY
            </code>
            .
          </>
        ),
      },
    ],
    externalUrl: "https://console.cloud.google.com",
    externalLabel: "Google Cloud Console",
  },
  {
    id: "screenshot",
    name: "Screenshot Service",
    subtitle: "Puppeteer on Railway · Full-page captures",
    category: "Visual Analysis",
    description:
      "Captures full-page screenshots of scanned URLs via a Puppeteer microservice hosted on Railway. Screenshots are stored in Supabase Storage and passed to Claude Vision for visual hierarchy and CTA effectiveness analysis.",
    status: "server-side",
    iconComponent: ScreenshotIcon,
    accentColor: "border-l-sky-500",
    envVars: [
      {
        name: "SCREENSHOT_SERVICE_URL",
        description: "Base URL of the Railway Puppeteer service (e.g. https://screenshot.up.railway.app)",
        resolved: null,
      },
      {
        name: "SCREENSHOT_SERVICE_API_KEY",
        description: "Authentication key for the screenshot service — set in both Railway and Supabase secrets",
        resolved: null,
      },
    ],
    usedBy: ["analyze-url"],
    setupSteps: [
      {
        n: 1,
        text: "Deploy the Puppeteer screenshot service to Railway (see /services/screenshot in the repo).",
      },
      {
        n: 2,
        text: (
          <>
            Copy the Railway deployment URL and set it as{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              SCREENSHOT_SERVICE_URL
            </code>{" "}
            in Supabase secrets.
          </>
        ),
      },
      {
        n: 3,
        text: "Generate a strong random API key and add it to both Railway environment variables and Supabase Edge Function secrets.",
      },
    ],
  },
  {
    id: "resend",
    name: "Resend",
    subtitle: "Transactional email · Onboarding sequences",
    category: "Email",
    description:
      "Delivers scan completion notifications, plan upgrade confirmations, password resets, and onboarding email sequences. React Email templates are compiled and sent via the send-email edge function.",
    status: "server-side",
    iconComponent: ResendIcon,
    accentColor: "border-l-pink-500",
    envVars: [
      {
        name: "RESEND_API_KEY",
        description: "Resend API key — set in Supabase Edge Function secrets",
        resolved: null,
      },
      {
        name: "SITE_URL",
        description: "Production site URL — used in email link generation (e.g. https://app.convertscan.ai)",
        resolved: null,
      },
    ],
    usedBy: ["send-email"],
    setupSteps: [
      {
        n: 1,
        text: (
          <>
            Go to{" "}
            <a
              href="https://resend.com/api-keys"
              target="_blank"
              rel="noopener noreferrer"
              className="text-primary underline font-medium hover:opacity-80 transition-opacity"
            >
              resend.com/api-keys
            </a>{" "}
            and create a new API key with full access.
          </>
        ),
      },
      {
        n: 2,
        text: "Add your sending domain to Resend and verify the required DNS records (SPF, DKIM).",
      },
      {
        n: 3,
        text: (
          <>
            In Supabase Dashboard → <strong>Edge Functions → Secrets</strong>, add{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              RESEND_API_KEY
            </code>{" "}
            and{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              SITE_URL
            </code>
            .
          </>
        ),
      },
    ],
    externalUrl: "https://resend.com",
    externalLabel: "Resend Dashboard",
  },
  {
    id: "supabase",
    name: "Supabase",
    subtitle: "PostgreSQL · Auth · Storage · Edge Functions",
    category: "Infrastructure",
    description:
      "Core infrastructure — provides authentication (Google OAuth + email/password), PostgreSQL with row-level security, Storage for screenshots and assets, and Edge Function hosting for all backend logic running in Deno runtime.",
    status: supabaseStatus,
    iconComponent: SupabaseIcon,
    accentColor: "border-l-emerald-500",
    envVars: [
      {
        name: "VITE_SUPABASE_URL",
        description: "Project URL — found in Supabase Project Settings → API",
        resolved: Boolean(import.meta.env.VITE_SUPABASE_URL),
      },
      {
        name: "VITE_SUPABASE_ANON_KEY",
        description: "Anonymous public key — safe to expose in the browser for client-side auth",
        resolved: Boolean(import.meta.env.VITE_SUPABASE_ANON_KEY),
      },
      {
        name: "SUPABASE_SERVICE_ROLE_KEY",
        description: "Service role key — used in edge functions for admin-level DB operations",
        resolved: null,
      },
    ],
    usedBy: ["analyze-url", "pagespeed", "dodo-checkout", "dodo-webhook", "send-email"],
    setupSteps: [
      {
        n: 1,
        text: (
          <>
            Create a project at{" "}
            <a
              href="https://supabase.com/dashboard"
              target="_blank"
              rel="noopener noreferrer"
              className="text-primary underline font-medium hover:opacity-80 transition-opacity"
            >
              supabase.com/dashboard
            </a>
            .
          </>
        ),
      },
      {
        n: 2,
        text: (
          <>
            Copy Project URL and anon key from <strong>Project Settings → API</strong> into your{" "}
            <code className="bg-muted border border-border/60 px-1.5 py-0.5 rounded text-xs font-mono">
              .env.local
            </code>{" "}
            file.
          </>
        ),
      },
      {
        n: 3,
        text: "Run all database migrations via the Supabase CLI: npx supabase db push",
      },
      {
        n: 4,
        text: "Deploy edge functions: npx supabase functions deploy",
      },
    ],
    externalUrl: "https://supabase.com/dashboard",
    externalLabel: "Supabase Dashboard",
  },
];

// ── Style maps ─────────────────────────────────────────────────────────────────

const STATUS_CONFIG: Record<
  IntegrationStatus,
  { label: string; icon: React.ElementType; className: string; dotColor: string }
> = {
  connected: {
    label: "Connected",
    icon: CheckCircle2,
    className: "bg-emerald-50 text-emerald-700 border border-emerald-200/60",
    dotColor: "bg-emerald-500",
  },
