// ── Sub-components ─────────────────────────────────────────────────────────────

function SetupStep({ n, text }: { n: number; text: React.ReactNode }) {
  return (
    <div className="flex gap-4">
      <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[11px] font-bold text-primary mt-0.5 tabular-nums">
        {n}
      </div>
      <p className="text-sm text-muted-foreground leading-relaxed pt-0.5">{text}</p>
    </div>
  );
}

function CopyButton({ value }: { value: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(value).then(() => {
      setCopied(true);
      toast.success(`Copied ${value}`);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  return (
    <button
      onClick={handleCopy}
      className="ml-1.5 inline-flex items-center justify-center h-5 w-5 rounded hover:bg-muted transition-colors shrink-0 opacity-0 group-hover/envrow:opacity-100 focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
      title={`Copy ${value}`}
    >
      {copied ? (
        <Check className="h-3 w-3 text-emerald-600" />
      ) : (
        <Copy className="h-3 w-3 text-muted-foreground" />
      )}
    </button>
  );
}

function EnvVarRow({ name, description, resolved }: EnvVar) {
  const isClientSide = resolved !== null;
  const hasMissing = isClientSide && !resolved;

  return (
    <div className="group/envrow flex items-start justify-between gap-4 py-3">
      <div className="min-w-0 flex-1">
        <div className="flex items-center">
          <code className="text-xs bg-muted/70 border border-border/50 px-2 py-1 rounded-md font-mono text-foreground/90 leading-none">
            {name}
          </code>
          <CopyButton value={name} />
        </div>
        <p className="text-xs text-muted-foreground mt-1.5 leading-relaxed">{description}</p>
      </div>
      <div className="shrink-0 pt-0.5">
        {isClientSide ? (
          <Badge
            className={cn(
              "text-xs px-2 py-0.5 font-medium",
              resolved
                ? "bg-emerald-50 text-emerald-700 border border-emerald-200/60"
                : "bg-red-50 text-red-700 border border-red-200/60"
            )}
          >
            {resolved ? "Set" : "Missing"}
          </Badge>
        ) : (
          <div className="flex items-center gap-1.5">
            <Lock className="h-3 w-3 text-muted-foreground/40" />
            <span className="text-xs text-muted-foreground/60 font-medium">Secret</span>
          </div>
        )}
        {hasMissing && (
          <p className="text-xs text-red-600/80 mt-1 font-medium">Required</p>
        )}
      </div>
    </div>
  );
}

function IntegrationCard({ integration }: { integration: IntegrationDef }) {
  const [open, setOpen] = useState(false);
  const [testStatus, setTestStatus] = useState<TestStatus>("idle");

  const { status } = integration;
  const statusConfig = STATUS_CONFIG[status];
  const StatusIcon = statusConfig.icon;
  const categoryStyle =
    CATEGORY_STYLE[integration.category] ?? {
      badge: "bg-muted/50 text-foreground/70 border border-border/50",
      iconBg: "bg-muted/50",
      iconColor: "text-foreground/70",
    };
  const testBadge = TEST_STATUS_BADGE[testStatus];
  const hasMissingEnvVars = integration.envVars.some((v) => v.resolved === false);

  const handleTest = (e: React.MouseEvent) => {
    e.stopPropagation();
    setTestStatus("testing");
    setTimeout(() => {
      if (status === "missing") {
        setTestStatus("failed");
        toast.error(`${integration.name} not configured — set the required env vars first.`);
      } else {
        setTestStatus("success");
        toast.success(`${integration.name} connection verified.`);
      }
    }, 1400);
  };

  const IconComp = integration.iconComponent;

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn(
        "rounded-xl border bg-card overflow-hidden transition-all duration-200",
        open
          ? cn(
              "border-border shadow-md border-l-4",
              integration.accentColor
            )
          : "border-border/60 shadow-sm hover:border-border hover:shadow-md"
      )}
    >
      {/* ── Row trigger ── */}
      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between px-5 py-4 text-left transition-colors hover:bg-muted/20 group">
          <div className="flex items-center gap-4">
            {/* Brand icon */}
            <div
              className={cn(
                "h-10 w-10 rounded-lg flex items-center justify-center shrink-0 border border-border/40",
                categoryStyle.iconBg
              )}
            >
              <IconComp
                className={cn("h-5 w-5", categoryStyle.iconColor)}
              />
            </div>

            {/* Name + subtitle */}
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <p className="text-sm font-semibold text-foreground">
                  {integration.name}
                </p>
                <Badge
                  className={cn(
                    "text-xs px-2 py-0 font-medium h-5",
                    categoryStyle.badge
                  )}
                >
                  {integration.category}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-0.5 leading-tight">
                {integration.subtitle}
              </p>
            </div>
          </div>

          {/* Status + chevron */}
          <div className="flex items-center gap-3 shrink-0 ml-4">
            <Badge
              className={cn(
                "text-xs px-2.5 py-1 flex items-center gap-1.5 font-medium",
                statusConfig.className
              )}
            >
              <span
                className={cn(
                  "h-1.5 w-1.5 rounded-full shrink-0",
                  statusConfig.dotColor
                )}
              />
              {statusConfig.label}
            </Badge>
            <ChevronDown
              className={cn(
                "h-4 w-4 text-muted-foreground/50 transition-transform duration-200 shrink-0",
                open && "rotate-180"
              )}
            />
          </div>
        </button>
      </CollapsibleTrigger>

      {/* ── Expanded panel ── */}
      <CollapsibleContent>
        <div className="px-5 pb-5">
          <Separator className="mb-5" />

          {/* Missing vars alert */}
          {hasMissingEnvVars && (
            <div className="flex items-start gap-3 rounded-lg border border-red-200/60 bg-red-50 px-4 py-3 mb-5">
              <AlertTriangle className="h-4 w-4 text-red-600 mt-0.5 shrink-0" />
              <p className="text-sm text-red-700 leading-relaxed">
                <span className="font-semibold">Action required</span> — configure the missing
                environment variables to activate this integration.
              </p>
            </div>
          )}

          {/* Tabbed detail view */}
          <Tabs defaultValue="overview">
            <TabsList className="h-9 bg-muted/50 border border-border/40 mb-5 w-auto">
              <TabsTrigger
                value="overview"
                className="text-xs px-3 h-7 data-[state=active]:bg-background data-[state=active]:shadow-sm"
              >
                Overview
              </TabsTrigger>
              <TabsTrigger
                value="configuration"
                className="text-xs px-3 h-7 data-[state=active]:bg-background data-[state=active]:shadow-sm"
              >
                Configuration
              </TabsTrigger>
              <TabsTrigger
                value="setup"
                className="text-xs px-3 h-7 data-[state=active]:bg-background data-[state=active]:shadow-sm"
              >
                Setup Guide
              </TabsTrigger>
            </TabsList>

            {/* Overview tab */}
            <TabsContent value="overview" className="mt-0 space-y-5">
              <p className="text-sm text-muted-foreground leading-relaxed">
                {integration.description}
              </p>

              <div>
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground/50 mb-2.5">
                  Used By
                </p>
                <div className="flex flex-wrap gap-1.5">
                  {integration.usedBy.map((fn) => (
                    <Badge
                      key={fn}
                      variant="outline"
                      className="text-xs font-mono border-border/60 text-muted-foreground bg-muted/30 hover:bg-muted/50 transition-colors"
                    >
                      {fn}
                    </Badge>
                  ))}
                </div>
              </div>

              {integration.externalUrl && (
                <div>
                  <a
                    href={integration.externalUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:opacity-80 transition-opacity"
                  >
                    <ExternalLink className="h-3.5 w-3.5" />
                    Open {integration.externalLabel ?? "Dashboard"}
                  </a>
                </div>
              )}
            </TabsContent>

            {/* Configuration tab */}
            <TabsContent value="configuration" className="mt-0 space-y-4">
              <div>
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground/50 mb-3">
                  Environment Variables
                </p>
                <div className="rounded-lg border border-border/50 divide-y divide-border/40 px-4 bg-card">
                  {integration.envVars.map((v) => (
                    <EnvVarRow key={v.name} {...v} />
                  ))}
                </div>
              </div>
              <div className="flex items-start gap-2 text-xs text-muted-foreground/60">
                <Lock className="h-3 w-3 mt-0.5 shrink-0" />
                <span>
                  Server-side secrets are managed in{" "}
                  <strong className="text-muted-foreground/80 font-medium">
                    Supabase Dashboard → Project Settings → Edge Functions → Secrets
                  </strong>{" "}
                  and are never exposed to the browser.
                </span>
              </div>
            </TabsContent>

            {/* Setup Guide tab */}
            <TabsContent value="setup" className="mt-0">
              <div className="rounded-lg border border-border/40 bg-muted/20 px-5 py-4 space-y-4">
                {integration.setupSteps.map((step) => (
                  <SetupStep key={step.n} n={step.n} text={step.text} />
                ))}
              </div>
            </TabsContent>
          </Tabs>

          <Separator className="mt-5 mb-4" />

          {/* Footer actions */}
          <div className="flex items-center justify-between flex-wrap gap-3">
            <div className="flex items-center gap-2">
              {testBadge && (
                <Badge className={cn("text-xs px-2.5 py-1", testBadge.className)}>
                  {testBadge.label}
                </Badge>
              )}
              {testStatus === "idle" && (
                <p className="text-xs text-muted-foreground/60">
                  Verify the service is reachable from edge functions.
                </p>
              )}
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleTest}
                disabled={testStatus === "testing"}
                className="text-xs h-8 border-border/60 hover:border-border"
              >
                {testStatus === "testing" ? (
                  <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" />
                ) : (
                  <FlaskConical className="mr-1.5 h-3.5 w-3.5" />
                )}
                Test Connection
              </Button>
              {integration.externalUrl && (
                <Button
                  variant="ghost"
                  size="sm"
                  asChild
                  className="text-xs h-8 text-muted-foreground hover:text-foreground"
                >
                  <a
                    href={integration.externalUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                    {integration.externalLabel ?? "Open Dashboard"}
                  </a>
                </Button>
              )}
            </div>
          </div>
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
}

// ── Summary stat chip ──────────────────────────────────────────────────────────

function StatChip({
  label,
  count,
  variant = "neutral",
}: {
  label: string;
  count: number;
  variant?: "neutral" | "success" | "warning" | "danger";
}) {
  const variants = {
    neutral: "border-border/50 bg-muted/20 text-foreground",
    success: "border-emerald-200/60 bg-emerald-50 text-emerald-800",
    warning: "border-amber-200/60 bg-amber-50 text-amber-800",
    danger:
      count > 0
        ? "border-red-200/60 bg-red-50 text-red-800"
        : "border-border/50 bg-muted/20 text-muted-foreground",
  };

  return (
    <div
      className={cn(
        "flex items-center gap-3 rounded-xl border px-4 py-3",
        variants[variant]
      )}
    >
      <span className="text-2xl font-bold tabular-nums leading-none">{count}</span>
      <span className="text-xs font-medium leading-tight">{label}</span>
    </div>
  );
}

